/** Native world/menu adapter. Independent initial container contents verify every purchase; no local synthetic receipt. */
public final class McBottleAcquisitionPort implements Port {
    private final java.util.function.Supplier<dev.veltraph.client.core.Module> parent;
    private final Minecraft client;private final FarmServices services;private final GameContextService context;private final McNavigator navigator;private final McSharedMovementNavigator mobility;private final dev.veltraph.client.navigation.mc.McParentMotionCleanup motionCleanup;private final McMenuAccess menus;private final McWorldService world;private final BottleFillWorkflow fill;private final McBottleFillPort fillPort;
    private BottleAcquisitionConfig.Contract contract;private Observation binding;private List<ItemStack> nativeInventory=List.of();private Map<Integer,ItemStack> nativeRows=Map.of();private AbstractContainerMenu nativeMenu;private Entity npc;private boolean interacted,returnWalking;private BottleFillWorkflow.Position walking;private String failure="";private int storageIndex,storageUsed,stackIndex,stackFilled;
    public McBottleAcquisitionPort(Minecraft client,ConfigService config,FarmServices services,GameContextService context){this(client,config,services,context,()->null);}
    public McBottleAcquisitionPort(Minecraft client,ConfigService config,FarmServices services,GameContextService context,java.util.function.Supplier<dev.veltraph.client.core.Module> parent){this.parent=parent;this.client=client;this.services=services;this.context=context;navigator=new McNavigator(client,services.input(),config);mobility=new McSharedMovementNavigator(client,services,config);motionCleanup=new dev.veltraph.client.navigation.mc.McParentMotionCleanup(client,services,parent);menus=new McMenuAccess(client);world=new McWorldService(client);fillPort=new McBottleFillPort(client,config,services,parent);fill=new BottleFillWorkflow(fillPort);}
    public boolean consumeExpectedTeleport(Vec3 position,long now){return walking!=null&&mobility.consumeExpectedTeleport(position,now)||fill.active()&&fillPort.consumeExpectedTeleport(position,now);}
    private boolean liveParent(){var modules=dev.veltraph.client.VeltraphBootstrap.moduleManager();var expected=parent.get();return client.isSameThread()&&modules!=null&&expected!=null&&modules.get(expected.id()).orElse(null)==expected&&expected.isEnabled()&&modules.inputOwner().orElse(null)==expected;}
    public void bind(BottleAcquisitionConfig.Contract contract){this.contract=contract;fillPort.beginOwner();npc=null;interacted=false;returnWalking=false;walking=null;failure="";storageIndex=storageUsed=stackFilled=0;stackIndex=-1;}
    public Optional<String> readiness(BottleAcquisitionConfig.Contract c){var o=read();if(!o.valid()||!o.closed()||!o.supported()||o.area()!=dev.veltraph.client.game.GameArea.ISLAND||!o.dimension().equals(c.acquisition().island().dimension()))return Optional.of("Closed supported exact Island owner required");if(o.inventory().stream().anyMatch(s->c.acquisition().glass().matches(s)||c.fill().water().matches(s))||o.inventory().stream().filter(BottleFillWorkflow.Stack::empty).count()<c.acquisition().stacks()+2||o.inventory().subList(0,9).stream().noneMatch(BottleFillWorkflow.Stack::empty))return Optional.of("No prepared glass/water and enough protected output/hotbar reserve required");var source=c.fill().source();var sourcePos=new net.minecraft.core.BlockPos(source.x(),source.y(),source.z());if(!client.level.getChunkSource().hasChunk(source.x()>>4,source.z()>>4)||!client.level.getFluidState(sourcePos).is(net.minecraft.tags.FluidTags.WATER)||!client.level.getFluidState(sourcePos).isSource())return Optional.of("Configured Island water source must be loaded before buying");for(var storage:c.storage()){var chest=storage.chest();if(!client.level.getChunkSource().hasChunk(chest.x()>>4,chest.z()>>4))return Optional.of("Configured Island chest route must be loaded before buying");var block=client.level.getBlockState(new net.minecraft.core.BlockPos(chest.x(),chest.y(),chest.z())).getBlock();if(block!=net.minecraft.world.level.block.Blocks.CHEST&&block!=net.minecraft.world.level.block.Blocks.TRAPPED_CHEST)return Optional.of("Configured storage route must be a native chest");}return Optional.empty();}
    public BottleFillWorkflow fillWorkflow(){return fill;}
    public Optional<dev.veltraph.client.metrics.FinancialActionReceipt> purchaseReceipt(Purchase purchase,dev.veltraph.client.core.Module owner,long sequence){var o=read();if(!fresh(o)||o.menu()!=purchase.verificationMenu()||!o.inventory().equals(purchase.after()))return Optional.empty();return Optional.of(new dev.veltraph.client.metrics.FinancialActionReceipt(UUID.randomUUID().toString(),owner,dev.veltraph.client.metrics.FinancialActionReceipt.Kind.PURCHASE,dev.veltraph.client.metrics.FinancialActionReceipt.Denomination.UNKNOWN,null,new dev.veltraph.client.metrics.FinancialOutcomeBindings.Scope(o.player(),o.world(),o.connection()),List.of(new dev.veltraph.client.metrics.FinancialActionReceipt.Evidence(purchase.requestMenu(),purchase.requestMenuId(),purchase.requestRevision(),purchase.requestRevision(),sequence,"one-exact64-purchase-request"),new dev.veltraph.client.metrics.FinancialActionReceipt.Evidence(o.menu(),nativeMenu.containerId,purchase.requestRevision(),o.revision(),sequence,"independent-server-initial64-bottle-delivery; quoted cost is budget only"))));}
    public String failure(){return failure;}
    @Override public Observation read(){if(!client.isSameThread())throw new IllegalStateException("Bottle parent requires client thread");var p=client.player;var level=client.level;var conn=client.getConnection();var receipt=NativeTeleportSignal.read(client);var inv=new ArrayList<BottleFillWorkflow.Stack>();var copies=new ArrayList<ItemStack>();var rows=new ArrayList<Slot>();var rowCopies=new HashMap<Integer,ItemStack>();var snapshot=menus.read();nativeMenu=p==null?null:p.containerMenu;
        if(p!=null){for(int i=0;i<36;i++){var s=p.getInventory().getItem(i);inv.add(McBottleFillPort.describe(s));copies.add(s.copy());}if(snapshot!=null)for(var s:nativeMenu.slots){var lore=s.getItem().get(DataComponents.LORE);rows.add(new Slot(s.index,s.container==p.getInventory(),McBottleFillPort.describe(s.getItem()),lore==null?List.of():lore.lines().stream().map(t->MenuSnapshot.clean(t.getString())).toList()));rowCopies.put(s.index,s.getItem().copy());}}
        Object menu=snapshot!=null?nativeMenu:client.gui.screen()!=null?client.gui.screen():p!=null&&nativeMenu!=p.inventoryMenu?nativeMenu:null;
        var feet=p==null?null:new Vec3(p.getX(),p.getY(),p.getZ());boolean valid=p!=null&&p.isAlive()&&level!=null&&p.level()==level&&conn!=null&&client.gameMode!=null&&!p.isPassenger()&&!p.isInLava()&&!p.getAbilities().flying;
        binding=new Observation(p,level,conn,p==null?null:p.getUUID(),level==null?"":level.dimension().identifier().toString(),context.current().area(),feet,p==null?0:p.getYRot(),p==null?0:p.getXRot(),valid,valid&&p.onGround()&&world.hasGroundSupport(feet,.3)&&world.bodyClear(feet,.3,1.8),menu,snapshot==null?"":snapshot.title(),nativeMenu==null?0:nativeMenu.containerId,nativeMenu==null?0:nativeMenu.getStateId(),nativeMenu==null?BottleFillWorkflow.Stack.EMPTY:McBottleFillPort.describe(nativeMenu.getCarried()),p==null?0:p.getInventory().getSelectedSlot(),inv,rows,receipt.serial(),receipt.position(),services.clock().nowMillis());nativeInventory=List.copyOf(copies);nativeRows=Map.copyOf(rowCopies);return binding;}
    private boolean fresh(Observation o){if(o!=binding||!o.valid()||client.player!=o.player()||client.level!=o.world()||client.getConnection()!=o.connection()||client.player.containerMenu!=nativeMenu||nativeMenu.getStateId()!=o.revision()||!nativeMenu.getCarried().isEmpty()||client.player.getInventory().getSelectedSlot()!=o.selected())return false;
        if(o.menu()==null&&client.gui.screen()!=null||o.menu()!=null&&(!(client.gui.screen() instanceof net.minecraft.client.gui.screens.inventory.AbstractContainerScreen<?> s)||s.getMenu()!=nativeMenu))return false;
        for(int i=0;i<36;i++)if(!ItemStack.matches(nativeInventory.get(i),client.player.getInventory().getItem(i)))return false;for(var s:nativeMenu.slots)if(nativeRows.containsKey(s.index)&&!ItemStack.matches(nativeRows.get(s.index),s.getItem()))return false;return true;}
    @Override public boolean command(Observation o,Landing landing){if(!fresh(o)||!o.closed())return false;release();npc=null;interacted=false;dev.veltraph.client.observation.unexpected.UnexpectedActions.expectTeleport(client,landing.position(),.9,BottleTeleportIntent.forActionTimeoutTicks(contract.acquisition().timeoutTicks()).millis());return new McServerCommandService(client).sendCommand(landing.command());}
    @Override public Progress walk(Observation o,BottleFillWorkflow.Position stand){if(!liveParent()||!fresh(o)||!o.closed())return Progress.FAILED;var target=new Vec3(stand.x()+.5,stand.y(),stand.z()+.5);if(walking==null&&o.position().distanceTo(target)<=.35&&o.supported()){mobility.stop();walking=null;return Progress.COMPLETE;}
        if(!stand.equals(walking)){mobility.stop();if(!mobility.start(navigator.position(new dev.veltraph.client.world.BlockPos(stand.x(),stand.y(),stand.z())),.35,SharedMovementPolicy.Purpose.GENERAL_TRAVEL))return Progress.FAILED;walking=stand;}var state=mobility.tick();if(state==McTravelNavigator.State.FAILED){mobility.stop();walking=null;return Progress.FAILED;}if(state==McTravelNavigator.State.ARRIVED){mobility.stop();walking=null;return Progress.COMPLETE;}return Progress.WAITING;}
    private Entity target(Profile p){var at=new net.minecraft.world.phys.Vec3(p.npcAnchor().x()+.5,p.npcAnchor().y(),p.npcAnchor().z()+.5);var matches=new ArrayList<Entity>();for(var e:client.level.entitiesForRendering())if(e instanceof Witch&&e.isAlive()&&!e.isRemoved()&&e.hasCustomName()&&MenuSnapshot.clean(e.getName().getString()).equals(p.npcName())&&BuiltInRegistries.ENTITY_TYPE.getKey(e.getType()).toString().equals(p.npcType())&&e.position().distanceTo(at)<5)matches.add(e);return matches.size()==1?matches.getFirst():null;}
    @Override public Progress npc(Observation o,Profile p,boolean issue){if(!fresh(o)||!o.closed())return Progress.FAILED;var exact=target(p);if(exact==null||npc!=null&&npc!=exact){failure="Exact named anchored Witch absent/replaced/ambiguous";return Progress.FAILED;}npc=exact;if(interacted)return Progress.COMPLETE;
        var walkingResult=walk(o,p.npcStand());if(walkingResult!=Progress.COMPLETE)return walkingResult;var eye=client.player.getEyePosition();var center=npc.getBoundingBox().getCenter();double reach=Math.min(4,client.player.entityInteractionRange());if(!client.player.hasLineOfSight(npc)||center.distanceTo(eye)>reach)return Progress.FAILED;
        var delta=center.subtract(eye);float yaw=(float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),pitch=(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z)));if(motionCleanup.beforePublication(2)){services.rotation().track(yaw,pitch);motionCleanup.remember();}
        if(Math.abs(Math.IEEEremainder(client.player.getYRot()-yaw,360))>5||Math.abs(client.player.getXRot()-pitch)>5||!(client.hitResult instanceof EntityHitResult hit)||hit.getEntity()!=npc||hit.getLocation().distanceTo(eye)>reach)return Progress.WAITING;
        if(!issue||!fresh(o)||target(p)!=npc)return Progress.FAILED;client.gameMode.interact(client.player,npc,hit,InteractionHand.MAIN_HAND);interacted=true;motionCleanup.release(mobility);return Progress.COMPLETE;}
    @Override public boolean click(Observation o,Slot slot){if(!fresh(o)||o.menu()==null||slot.player()||slot.stack().tool()||!o.rows().contains(slot))return false;var snapshot=menus.read();return snapshot!=null&&menus.click(snapshot,slot.id());}
    @Override public boolean close(Observation o){if(!fresh(o)||o.menu()==null)return false;client.player.closeContainer();interacted=false;return true;}
    private BottleFillWorkflow.Request chunkRequest(){var f=contract.fill();var destination=contract.storage().get(storageIndex);int quantity=Math.min(64-stackFilled,destination.capacity()-storageUsed);return new BottleFillWorkflow.Request(f.glass(),f.water(),quantity,f.dimension(),f.source(),f.sourceStand(),destination.chest(),destination.stand(),destination.title(),f.delayTicks(),f.timeoutTicks());}
    private boolean beginChunk(long tick){try{if(storageIndex>=contract.storage().size())return false;fill.startBatched(chunkRequest(),tick,stackIndex,contract.reserveSlots());return fill.active();}catch(RuntimeException e){failure=e.getMessage();return false;}}
    @Override public boolean beginFill(int index,long tick){var o=read();if(!fresh(o)||!o.closed()||!McBottleFillPort.vanillaWater(contract.fill().water())||index<0||index>=36||!contract.acquisition().glass().matches(o.inventory().get(index))||o.inventory().get(index).count()!=64)return false;stackIndex=index;stackFilled=0;return beginChunk(tick);}
    @Override public Progress fill(long tick){fill.tick(tick);if(fill.active())return Progress.WAITING;if(fill.state()!=BottleFillWorkflow.State.COMPLETE)return Progress.FAILED;int accepted=fill.completed();stackFilled+=accepted;storageUsed+=accepted;if(storageUsed==contract.storage().get(storageIndex).capacity()){storageIndex++;storageUsed=0;}if(stackFilled==64)return Progress.COMPLETE;if(!beginChunk(tick))return Progress.FAILED;return Progress.WAITING;}
    @Override public int filled(){return stackFilled;}
    @Override public void cancelFill(){fill.cancel();}
    @Override public boolean returnPose(Observation o,Vec3 position,float yaw,float pitch){if(!liveParent()||!fresh(o)||!o.closed())return false;if(returnWalking||o.position().distanceTo(position)>.25||!o.supported()){if(!returnWalking){mobility.stop();if(!mobility.start(position,.25,SharedMovementPolicy.Purpose.EXACT_RETURN))return false;returnWalking=true;}var state=mobility.tick();if(state==McTravelNavigator.State.FAILED||state==McTravelNavigator.State.ARRIVED){mobility.stop();returnWalking=false;}return false;}mobility.stop();returnWalking=false;if(motionCleanup.beforePublication(2)){services.rotation().track(yaw,pitch);motionCleanup.remember();}return Math.abs(Math.IEEEremainder(o.yaw()-yaw,360))<=.05&&Math.abs(o.pitch()-pitch)<=.05;}
    @Override public void release(){motionCleanup.release(mobility);walking=null;}
}
